


/** A physical or logical place a merchant operates from. Locations own geography and, when inventory is enabled, an inventory capability block. */ export type Location = { /** Published postal address. */ "address"?: { "city"?: string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country"?: string; "line1"?: string; "line2"?: string; "postal_code"?: string; /** State, province, or region. */ "state"?: string; }; /** Published geographic coordinate. */ "coordinate"?: { "latitude"?: number; "longitude"?: number; }; /** Source of the stored latitude and longitude. */ "coordinate_source"?: "merchant_supplied" | "geocoded" | null | (string & {}) | null; /** Time the Location was created. Format: date-time. */ "created_at": string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Optimistic-concurrency revision for geography writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "geography_revision": string; /** Inventory allocation capability at this Location. */ "inventory"?: { "allocation_status": "active" | "inactive" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "created_at": string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "inventory_revision": string; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; }; /** Stable Location ID. */ "location_id": string; /** Caller-owned metadata. */ "metadata": Record<string, string>; /** Merchant-facing Location name. */ "name": string; /** Provider-normalized address used for geography evaluation. */ "normalized_address"?: { "city"?: string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country"?: string; "line1"?: string; "line2"?: string; "postal_code"?: string; /** State, province, or region. */ "state"?: string; }; /** Current Location lifecycle status. */ "status": "active" | "inactive" | "archived" | (string & {}); /** IANA timezone for local schedules. */ "timezone": string; /** Time the Location last changed. Format: date-time. */ "updated_at": string; /** Normalized reason address validation failed. */ "validation_failure_reason"?: string; /** Address validation status. */ "validation_status": "not_validated" | "validated" | "merchant_verified" | (string & {}); /** Optimistic-concurrency version for general Location writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; };
